{"code_block": "import time, sys
# Load board
board = [list(row) for row in ["ABRL", "EITE", "IONS", "FPEI"]]
R = len(board)
C = len(board[0])
DIRS = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if not (dr == 0 and dc == 0)]

print("Loading dictionary...")
# Load word dictionary and build word_set and prefix_set for words length <= 16
word_set = set()
prefix_set = set()
with open("/home/user/words_alpha.txt", "r", encoding="utf-8") as f:
    for word in f:
        w = word.strip()
        lw = len(w)
        if lw > 16:
            continue
        if lw >= 3:
            word_set.add(w)
        # generate prefixes up to length 16
        for i in range(1, min(lw, 16)+1):
            prefix_set.add(w[:i])
print(f"Loaded {len(word_set)} words (len <=16).")

# DFS
max_len = 0
longest_words = []

import sys
sys.setrecursionlimit(10000)

def dfs(r, c, path, visited):
    global max_len, longest_words
    cur_char = board[r][c].lower()
    new_path = path + cur_char
    if new_path not in prefix_set:
        return
    if len(new_path) >= 3 and new_path in word_set:
        cur_len = len(new_path)
        if cur_len > max_len:
            max_len = cur_len
            longest_words = [new_path]
        elif cur_len == max_len:
            longest_words.append(new_path)
    for dr, dc in DIRS:
        nr, nc = r + dr, c + dc
        if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in visited:
            dfs(nr, nc, new_path, visited | {(nr, nc)})

for i in range(R):
    for j in range(C):
        dfs(i, j, "", {(i, j)})

if longest_words:
    best_word = min(longest_words)
else:
    best_word = ""
print(f"Max length: {max_len}, best_word: {best_word}, count longest words: {len(longest_words)}")", "sandbox_id": "ie19fo7jk0w77akboazsq-6532622b"}

{"code_block": "import time
# Load dictionary again but now produce a set of words length <=16
word_set = set()
with open("/home/user/words_alpha.txt", "r", encoding="utf-8") as f:
    for word in f:
        w = word.strip()
        if 3 <= len(w) <= 16:
            word_set.add(w)
# Now board specifics
board = [list(row) for row in ["ABRL", "EITE", "IONS", "FPEI"]]
R, C = 4, 4
DIRS = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if not (dr == 0 and dc == 0)]

# Build prefix_set for all words in word_set
prefix_set = set()
for w in word_set:
    for i in range(1, len(w)+1):
        prefix_set.add(w[:i])
# DFS to find all words reachable; we want set of words reachable
reachable_words = set()

def dfs(r, c, path, visited):
    cur_char = board[r][c].lower()
    new_path = path + cur_char
    if new_path not in prefix_set:
        return
    # record if >=3 (implicitly already recorded)
    if len(new_path) >= 3 and new_path in word_set:
        reachable_words.add(new_path)
    for dr, dc in DIRS:
        nr, nc = r+dr, c+dc
        if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in visited:
            dfs(nr, nc, new_path, visited | {(nr, nc)})

for i in range(R):
    for j in range(C):
        dfs(i, j, "", {(i, j)})
# Now find max length
if reachable_words:
    max_len = max(len(w) for w in reachable_words)
    longest_words = [w for w in reachable_words if len(w) == max_len]
    best_word = min(longest_words)
else:
    max_len = 0
    longest_words = []
    best_word = ""
print(f"max_len={max_len}, best_word={best_word}, count longest={len(longest_words)}")
print(f"All longest words sorted: {sorted(longest_words)}")
print(f"Number reachable words total: {len(reachable_words)}")", "sandbox_id": "ie19fo7jk0w77akboazsq-6532622b"}

